contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint putAmt, uint lock) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmt)); require(putAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmt);

        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        bool putReverted;
        c.Put{value: putAmt}(lock); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            putReverted = true;
        } else {
            putReverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        assert(
            putReverted
                ? (cBalAfter == cBalBefore && thisBalAfter == thisBalBefore)
                : (cBalAfter == cBalBefore + putAmt && thisBalAfter == thisBalBefore - putAmt)
        );
    }

    receive() external payable {}
}

