// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 putAmt, uint256 lock) internal {
        putAmt = bound(putAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmt);
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;
        bool putReverted;
        try c.Put{value: putAmt}(lock) {
            putReverted = false;
        } catch {
            putReverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;
        assertTrue(putReverted
                ? (cBalAfter == cBalBefore && thisBalAfter == thisBalBefore)
                : (cBalAfter == cBalBefore + putAmt && thisBalAfter == thisBalBefore - putAmt));
    }

    function testFuzz_run(uint256 putAmt, uint256 lock) public {
        _run(putAmt, lock);
    }

    receive() external payable {}
}
